function V_PORT_NAME_SEC1FormatTrigger return boolean is
V_NAME VARCHAR2(100);
BEGIN
	IF :P_CURR_PORT_CD = 99 THEN
	RETURN(TRUE);
	ELSE

  SELECT PORT_NAME
  INTO   V_NAME
  FROM   SD_PORTS
  WHERE  PORT_CD = :P_CURR_PORT_CD ;
  SRW.SET_FIELD_CHAR(0,V_NAME);	
 	RETURN(TRUE);
 END IF;
EXCEPTION 
	WHEN NO_DATA_FOUND THEN
--RETURN(NULL);
	RETURN(TRUE);


	RETURN(TRUE);
END;

      function AfterPForm return boolean is
begin

  IF (:P_BUS_ID IS NOT NULL OR :P_BUS_ID_BRNCH IS NOT NULL) THEN
  	:P_CLNT_ID:=NULL;	
  END IF;
  return (TRUE);
end;
